const data = $input.first().json;
const webhook = $('Notion Webhook Trigger').first().json;

// Extract conversation details
const name = data.properties?.Name?.title?.[0]?.text?.content || 'Unknown';
const email = data.properties?.Email?.email || 'No email provided';
const status = data.properties?.Status?.select?.name || 'Unknown';
const sentiment = data.properties?.Sentiment?.select?.name || 'Unknown';
const interestLevel = data.properties?.['Interest Level']?.select?.name || 'Unknown';
const topics = data.properties?.['Topics Discussed']?.multi_select?.map(t => t.name).join(', ') || 'None specified';
const summary = data.properties?.['Conversation Summary']?.rich_text?.[0]?.text?.content || 'No summary available';
const transcript = data.properties?.['Full Transcript']?.rich_text?.[0]?.text?.content || 'No transcript available';
const phone = data.properties?.Phone?.phone_number || 'No phone provided';
const followUpRequired = data.properties?.['Follow-up Required']?.checkbox ? 'Yes' : 'No';
const updatedTime = new Date(data.last_edited_time).toLocaleString();
const createdTime = new Date(data.created_time).toLocaleString();

// Determine if this is a new conversation or update
const isNew = webhook.event === 'page.created' || data.created_time === data.last_edited_time;
const actionType = isNew ? 'New Conversation' : 'Conversation Updated';

// Create email content
const emailContent = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <h2 style="color: #2563eb; border-bottom: 2px solid #e5e7eb; padding-bottom: 10px;">
    🤖 ${actionType}: Portfolio Agent Activity
  </h2>

  <div style="background-color: #f8fafc; padding: 20px; border-radius: 8px; margin: 20px 0;">
    <h3 style="margin-top: 0; color: #1e293b;">Contact Information</h3>
    <p><strong>Name:</strong> ${name}</p>
    <p><strong>Email:</strong> ${email}</p>
    <p><strong>Phone:</strong> ${phone}</p>
    <p><strong>Status:</strong> <span style="background: #dbeafe; padding: 2px 8px; border-radius: 4px;">${status}</span></p>
  </div>

  <div style="background-color: #f0fdf4; padding: 20px; border-radius: 8px; margin: 20px 0;">
    <h3 style="margin-top: 0; color: #166534;">Conversation Analysis</h3>
    <p><strong>Sentiment:</strong> <span style="background: #bbf7d0; padding: 2px 8px; border-radius: 4px;">${sentiment}</span></p>
    <p><strong>Interest Level:</strong> ${interestLevel}</p>
    <p><strong>Topics Discussed:</strong> ${topics}</p>
    <p><strong>Follow-up Required:</strong> ${followUpRequired}</p>
  </div>

  <div style="background-color: #fefce8; padding: 20px; border-radius: 8px; margin: 20px 0;">
    <h3 style="margin-top: 0; color: #a16207;">Conversation Summary</h3>
    <p style="background: white; padding: 10px; border-radius: 4px; border-left: 4px solid #eab308;">${summary}</p>
  </div>

  <div style="background-color: #fdf2f8; padding: 20px; border-radius: 8px; margin: 20px 0;">
    <h3 style="margin-top: 0; color: #be185d;">Full Transcript</h3>
    <div style="background: white; padding: 10px; border-radius: 4px; max-height: 200px; overflow-y: auto; white-space: pre-wrap; font-family: monospace; font-size: 12px;">${transcript}</div>
  </div>

  <div style="background-color: #f1f5f9; padding: 20px; border-radius: 8px; margin: 20px 0;">
    <h3 style="margin-top: 0; color: #475569;">Timestamps</h3>
    <p><strong>Created:</strong> ${createdTime}</p>
    <p><strong>Last Updated:</strong> ${updatedTime}</p>
  </div>

  <div style="text-align: center; margin: 30px 0;">
    <a href="${data.url}" 
       style="background: #2563eb; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; display: inline-block;">
       📋 View in Notion
    </a>
  </div>

  <hr style="margin: 30px 0; border: none; border-top: 1px solid #e5e7eb;">
  <p style="text-align: center; color: #6b7280; font-size: 12px;">
    This alert was triggered by your Portfolio Agent automation system.
  </p>
</div>
`;

return {
  subject: `🤖 ${actionType}: ${name} - ${status}`,
  html: emailContent,
  name: name,
  email: email,
  status: status,
  sentiment: sentiment,
  actionType: actionType
};
